"""
Architecture Lab - Class-Based Game Skeleton
Lumexa Game Creator Path - Course 03, Lesson 03
"""
import pygame
import sys
from enum import Enum, auto

pygame.init()
WIDTH, HEIGHT = 800, 600
screen = pygame.display.set_mode((WIDTH, HEIGHT))
pygame.display.set_caption("Architecture Lab")
clock = pygame.time.Clock()
FPS = 60
font = pygame.font.SysFont("consolas", 28)

WHITE = (235, 235, 240)
BG = (10, 12, 28)
PLAYER_COLOR = (80, 200, 255)
GEM_COLOR = (255, 210, 60)
HAZARD_COLOR = (230, 70, 70)


# ---------------------------------------------------------------------------
# STATE MACHINE
# ---------------------------------------------------------------------------
class GameState(Enum):
    MENU = auto()
    PLAYING = auto()
    PAUSED = auto()
    GAME_OVER = auto()
    WIN = auto()


class GameStateMachine:
    """Tracks the current game state and defines legal transitions."""

    ALLOWED_TRANSITIONS = {
        GameState.MENU: {GameState.PLAYING},
        GameState.PLAYING: {GameState.PAUSED, GameState.GAME_OVER, GameState.WIN},
        GameState.PAUSED: {GameState.PLAYING, GameState.MENU},
        GameState.GAME_OVER: {GameState.MENU, GameState.PLAYING},
        GameState.WIN: {GameState.MENU, GameState.PLAYING},
    }

    def __init__(self, initial_state=GameState.MENU):
        self.state = initial_state

    def change_state(self, new_state):
        if new_state in self.ALLOWED_TRANSITIONS.get(self.state, set()):
            self.state = new_state
            return True
        print(f"Illegal transition: {self.state} -> {new_state}")
        return False

    def is_in(self, *states):
        return self.state in states


# ---------------------------------------------------------------------------
# ENTITIES ("is-a" hierarchy via inheritance)
# ---------------------------------------------------------------------------
class Entity:
    """Base class for anything that exists in the game world."""

    def __init__(self, x, y, width, height, color):
        self.rect = pygame.Rect(x, y, width, height)
        self.color = color
        self.active = True  # inactive entities are removed by the game

    def update(self, dt):
        """Override in subclasses. dt = seconds since last frame."""
        pass

    def draw(self, surface):
        pygame.draw.rect(surface, self.color, self.rect, border_radius=4)


class Inventory:
    """A 'has-a' component owned by Player - composition, not inheritance."""

    def __init__(self):
        self.items = {}

    def add(self, item_name, amount=1):
        self.items[item_name] = self.items.get(item_name, 0) + amount

    def count(self, item_name):
        return self.items.get(item_name, 0)


class Player(Entity):
    """The player entity - 'is-a' Entity, 'has-a' Inventory (composition)."""

    def __init__(self, x, y):
        super().__init__(x, y, 32, 32, PLAYER_COLOR)
        self.speed = 240  # pixels per second
        self.health = 3
        self.inventory = Inventory()  # composition: Player HAS-A Inventory
        self.invincible_timer = 0.0

    def handle_input(self, keys, dt):
        dx = dy = 0
        if keys[pygame.K_LEFT] or keys[pygame.K_a]:
            dx = -1
        if keys[pygame.K_RIGHT] or keys[pygame.K_d]:
            dx = 1
        if keys[pygame.K_UP] or keys[pygame.K_w]:
            dy = -1
        if keys[pygame.K_DOWN] or keys[pygame.K_s]:
            dy = 1
        self.rect.x += int(dx * self.speed * dt)
        self.rect.y += int(dy * self.speed * dt)
        self.rect.clamp_ip(screen.get_rect())

    def update(self, dt):
        if self.invincible_timer > 0:
            self.invincible_timer -= dt

    def take_damage(self, amount):
        """Encapsulation: outside code never touches self.health directly."""
        if self.invincible_timer > 0:
            return
        self.health -= amount
        self.invincible_timer = 1.0  # 1 second of invincibility after a hit

    def draw(self, surface):
        # Flicker while invincible - visible feedback for a hidden timer
        if self.invincible_timer <= 0 or int(self.invincible_timer * 10) % 2 == 0:
            super().draw(surface)


class Collectible(Entity):
    """A gem the player can pick up."""

    def __init__(self, x, y):
        super().__init__(x, y, 20, 20, GEM_COLOR)

    def draw(self, surface):
        pygame.draw.circle(surface, self.color, self.rect.center, 10)


class Hazard(Entity):
    """A hazard that damages the player on contact."""

    def __init__(self, x, y):
        super().__init__(x, y, 30, 30, HAZARD_COLOR)


# ---------------------------------------------------------------------------
# GAME CLASS - ties architecture together
# ---------------------------------------------------------------------------
class Game:
    def __init__(self):
        self.fsm = GameStateMachine()
        self.player = None
        self.entities = []
        self.score = 0

    def start_new_game(self):
        self.player = Player(WIDTH // 2, HEIGHT // 2)
        self.entities = [
            Collectible(150, 150), Collectible(600, 200), Collectible(400, 450),
            Hazard(300, 300), Hazard(500, 400),
        ]
        self.score = 0
        self.fsm.change_state(GameState.PLAYING)

    def handle_event(self, event):
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_RETURN and self.fsm.is_in(GameState.MENU):
                self.start_new_game()
            elif event.key == pygame.K_p and self.fsm.is_in(GameState.PLAYING):
                self.fsm.change_state(GameState.PAUSED)
            elif event.key == pygame.K_p and self.fsm.is_in(GameState.PAUSED):
                self.fsm.change_state(GameState.PLAYING)
            elif event.key == pygame.K_r and self.fsm.is_in(GameState.GAME_OVER, GameState.WIN):
                self.fsm.change_state(GameState.MENU)

    def update(self, dt):
        if not self.fsm.is_in(GameState.PLAYING):
            return
        keys = pygame.key.get_pressed()
        self.player.handle_input(keys, dt)
        self.player.update(dt)

        for entity in self.entities[:]:
            entity.update(dt)
            if not entity.rect.colliderect(self.player.rect):
                continue
            if isinstance(entity, Collectible):
                self.score += 10
                self.player.inventory.add("gem")
                self.entities.remove(entity)
            elif isinstance(entity, Hazard):
                self.player.take_damage(1)

        if self.player.health <= 0:
            self.fsm.change_state(GameState.GAME_OVER)
        elif not any(isinstance(e, Collectible) for e in self.entities):
            self.fsm.change_state(GameState.WIN)

    def draw(self, surface):
        surface.fill(BG)
        if self.fsm.is_in(GameState.MENU):
            self._draw_center_text(surface, "ARCHITECTURE LAB", "Press ENTER to start")
        elif self.fsm.is_in(GameState.PLAYING, GameState.PAUSED):
            for entity in self.entities:
                entity.draw(surface)
            self.player.draw(surface)
            hud = font.render(
                f"Score: {self.score}  HP: {self.player.health}  Gems: {self.player.inventory.count('gem')}",
                True, WHITE,
            )
            surface.blit(hud, (10, 10))
            if self.fsm.is_in(GameState.PAUSED):
                self._draw_center_text(surface, "PAUSED", "Press P to resume")
        elif self.fsm.is_in(GameState.GAME_OVER):
            self._draw_center_text(surface, "GAME OVER", "Press R to return to menu")
        elif self.fsm.is_in(GameState.WIN):
            self._draw_center_text(surface, "YOU WIN!", "Press R to return to menu")

    def _draw_center_text(self, surface, big_text, small_text):
        big = font.render(big_text, True, WHITE)
        small = font.render(small_text, True, WHITE)
        surface.blit(big, (WIDTH // 2 - big.get_width() // 2, HEIGHT // 2 - 30))
        surface.blit(small, (WIDTH // 2 - small.get_width() // 2, HEIGHT // 2 + 10))


def main():
    game = Game()
    running = True
    while running:
        dt = clock.tick(FPS) / 1000.0
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                running = False
            else:
                game.handle_event(event)
        game.update(dt)
        game.draw(screen)
        pygame.display.flip()
    pygame.quit()
    sys.exit()


if __name__ == "__main__":
    main()

using UnityEngine;

// Every Unity gameplay script inherits from MonoBehaviour, which is what
// lets Unity treat this class as an attachable Component in the Inspector.
public class PlayerMovement : MonoBehaviour
{
    [Header("Movement Settings")]
    public float moveSpeed = 5f;      // units per second, editable in the Inspector
    public float jumpForce = 6f;      // upward force applied when jumping

    [Header("Ground Check")]
    public float groundCheckDistance = 0.6f;

    private Rigidbody rb;             // cached reference to this object's Rigidbody
    private bool isGrounded;

    // Start() runs once, before the first frame - used for one-time setup.
    void Start()
    {
        rb = GetComponent<Rigidbody>();
        if (rb == null)
        {
            Debug.LogError("PlayerMovement requires a Rigidbody component on this GameObject.");
        }
    }

    // Update() runs once per frame - used for input reading and per-frame logic.
    void Update()
    {
        // Read raw input axes (configured in Unity's Input Manager by default:
        // Horizontal = A/D or Left/Right, Vertical = W/S or Up/Down).
        float horizontal = Input.GetAxis("Horizontal");
        float vertical = Input.GetAxis("Vertical");

        Vector3 moveDirection = new Vector3(horizontal, 0f, vertical).normalized;
        Vector3 targetVelocity = moveDirection * moveSpeed;

        // Preserve the current vertical velocity (gravity/jumping) while
        // overwriting horizontal movement - this is standard for physics-based
        // character movement so gravity is not fought against every frame.
        rb.linearVelocity = new Vector3(targetVelocity.x, rb.linearVelocity.y, targetVelocity.z);

        // Simple grounded check using a downward raycast from the player's center.
        isGrounded = Physics.Raycast(transform.position, Vector3.down, groundCheckDistance);

        if (isGrounded && Input.GetKeyDown(KeyCode.Space))
        {
            rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
        }
    }
}

"""
UI and HUD Lab
Lumexa Game Creator Path - Course 03, Lesson 05
"""
import pygame
import sys
from enum import Enum, auto

pygame.init()
WIDTH, HEIGHT = 800, 600
screen = pygame.display.set_mode((WIDTH, HEIGHT))
pygame.display.set_caption("UI and HUD Lab")
clock = pygame.time.Clock()
FPS = 60

# ---- Consistent color palette (used everywhere = consistency principle) ----
BG = (10, 12, 28)
PANEL = (24, 28, 54)
BUTTON = (46, 58, 110)
BUTTON_HOVER = (70, 90, 160)
ACCENT = (80, 220, 255)
WHITE = (235, 235, 240)
HEALTH_GREEN = (80, 220, 130)
HEALTH_RED = (230, 70, 70)

title_font = pygame.font.SysFont("consolas", 48, bold=True)
ui_font = pygame.font.SysFont("consolas", 26)
hud_font = pygame.font.SysFont("consolas", 22)


class Button:
    """A reusable, class-based button with hover feedback and a click callback."""

    def __init__(self, rect, text, on_click):
        self.rect = pygame.Rect(rect)
        self.text = text
        self.on_click = on_click
        self.hovered = False

    def update(self, mouse_pos):
        self.hovered = self.rect.collidepoint(mouse_pos)

    def handle_event(self, event):
        if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
            if self.rect.collidepoint(event.pos):
                self.on_click()

    def draw(self, surface):
        color = BUTTON_HOVER if self.hovered else BUTTON
        pygame.draw.rect(surface, color, self.rect, border_radius=10)
        pygame.draw.rect(surface, ACCENT, self.rect, width=2, border_radius=10)
        label = ui_font.render(self.text, True, WHITE)
        surface.blit(
            label,
            (self.rect.centerx - label.get_width() // 2, self.rect.centery - label.get_height() // 2),
        )


class Menu:
    """A full-screen menu made of a title and a vertical stack of buttons."""

    def __init__(self, title, button_defs):
        """button_defs: list of (label, callback) tuples."""
        self.title = title
        self.buttons = []
        start_y = HEIGHT // 2 - 20
        for i, (label, callback) in enumerate(button_defs):
            rect = (WIDTH // 2 - 120, start_y + i * 70, 240, 50)
            self.buttons.append(Button(rect, label, callback))

    def handle_event(self, event):
        for button in self.buttons:
            button.handle_event(event)

    def update(self, mouse_pos):
        for button in self.buttons:
            button.update(mouse_pos)

    def draw(self, surface):
        surface.fill(BG)
        label = title_font.render(self.title, True, ACCENT)
        surface.blit(label, (WIDTH // 2 - label.get_width() // 2, 110))
        for button in self.buttons:
            button.draw(surface)


class HUD:
    """Persistent in-game overlay: health bar, score, and objective text.
    Designed to sit in the corners so it never blocks the play area's center.
    """

    def __init__(self):
        self.max_health = 5

    def draw(self, surface, health, score, objective_text):
        # --- Health bar (top-left, high visual priority - critical info) ---
        bar_width, bar_height = 160, 22
        x, y = 16, 16
        pygame.draw.rect(surface, PANEL, (x - 2, y - 2, bar_width + 4, bar_height + 4), border_radius=6)
        fill_ratio = max(0, health) / self.max_health
        fill_color = HEALTH_GREEN if fill_ratio > 0.4 else HEALTH_RED
        pygame.draw.rect(surface, fill_color, (x, y, int(bar_width * fill_ratio), bar_height), border_radius=4)
        hp_label = hud_font.render(f"HP {health}/{self.max_health}", True, WHITE)
        surface.blit(hp_label, (x + bar_width + 12, y - 2))

        # --- Score (top-right, secondary priority) ---
        score_label = hud_font.render(f"Score: {score}", True, WHITE)
        surface.blit(score_label, (WIDTH - score_label.get_width() - 16, 16))

        # --- Objective (bottom-center, guidance without blocking play area) ---
        obj_label = hud_font.render(objective_text, True, WHITE)
        surface.blit(obj_label, (WIDTH // 2 - obj_label.get_width() // 2, HEIGHT - 34))


class AppState(Enum):
    MENU = auto()
    PLAYING = auto()
    PAUSED = auto()
    GAME_OVER = auto()


class App:
    def __init__(self):
        self.state = AppState.MENU
        self.hud = HUD()
        self.health = 5
        self.score = 0
        self.main_menu = Menu("UI & HUD LAB", [
            ("Start Game", self.start_game),
            ("Quit", self.quit_game),
        ])
        self.pause_menu = Menu("PAUSED", [
            ("Resume", self.resume_game),
            ("Main Menu", self.go_to_menu),
        ])
        self.game_over_menu = Menu("GAME OVER", [
            ("Restart", self.start_game),
            ("Main Menu", self.go_to_menu),
        ])

    def start_game(self):
        self.health = 5
        self.score = 0
        self.state = AppState.PLAYING

    def resume_game(self):
        self.state = AppState.PLAYING

    def go_to_menu(self):
        self.state = AppState.MENU

    def quit_game(self):
        pygame.quit()
        sys.exit()

    def handle_event(self, event):
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_p and self.state == AppState.PLAYING:
                self.state = AppState.PAUSED
            elif event.key == pygame.K_SPACE and self.state == AppState.PLAYING:
                self.score += 10  # simulate scoring for the demo
            elif event.key == pygame.K_h and self.state == AppState.PLAYING:
                self.health -= 1  # simulate taking damage for the demo
                if self.health <= 0:
                    self.state = AppState.GAME_OVER

        if self.state == AppState.MENU:
            self.main_menu.handle_event(event)
        elif self.state == AppState.PAUSED:
            self.pause_menu.handle_event(event)
        elif self.state == AppState.GAME_OVER:
            self.game_over_menu.handle_event(event)

    def update(self, mouse_pos):
        if self.state == AppState.MENU:
            self.main_menu.update(mouse_pos)
        elif self.state == AppState.PAUSED:
            self.pause_menu.update(mouse_pos)
        elif self.state == AppState.GAME_OVER:
            self.game_over_menu.update(mouse_pos)

    def draw(self, surface):
        if self.state == AppState.MENU:
            self.main_menu.draw(surface)
        elif self.state == AppState.PLAYING:
            surface.fill(BG)
            self.hud.draw(surface, self.health, self.score, "Objective: SPACE to score, H to take damage, P to pause")
        elif self.state == AppState.PAUSED:
            surface.fill(BG)
            self.hud.draw(surface, self.health, self.score, "Paused")
            self.pause_menu.draw(surface)
        elif self.state == AppState.GAME_OVER:
            self.game_over_menu.draw(surface)


def main():
    app = App()
    running = True
    while running:
        clock.tick(FPS)
        mouse_pos = pygame.mouse.get_pos()
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                running = False
            else:
                app.handle_event(event)
        app.update(mouse_pos)
        app.draw(screen)
        pygame.display.flip()
    pygame.quit()
    sys.exit()


if __name__ == "__main__":
    main()

"""
Playtest Telemetry Module
Lumexa Game Creator Path - Course 03, Lesson 06
Drop this class into any prototype to start collecting objective playtest data.
"""
import time
import json


class Telemetry:
    """Collects lightweight, objective gameplay events during a playtest session."""

    def __init__(self):
        self.session_start = time.time()
        self.events = []          # a full timestamped log of every event
        self.death_positions = [] # (level, x, y) for every death - reveals hotspots
        self.level_times = {}     # level_index -> list of completion times in seconds
        self._level_start_time = None

    def log_event(self, event_type, **details):
        self.events.append({
            "type": event_type,
            "time_since_start": round(time.time() - self.session_start, 2),
            **details,
        })

    def record_level_start(self, level_index):
        self._level_start_time = time.time()
        self.log_event("level_start", level=level_index)

    def record_death(self, level_index, x, y):
        self.death_positions.append((level_index, x, y))
        self.log_event("death", level=level_index, x=x, y=y)

    def record_level_complete(self, level_index):
        if self._level_start_time is not None:
            duration = round(time.time() - self._level_start_time, 2)
            self.level_times.setdefault(level_index, []).append(duration)
            self.log_event("level_complete", level=level_index, duration=duration)

    def find_death_hotspots(self, min_deaths=3, radius=40):
        """Groups nearby deaths to find hazard placements that killed multiple times.
        This is exactly how a designer spots an unfair/unclear hazard using data
        rather than guessing from a handful of watched sessions.
        """
        hotspots = []
        checked = set()
        for i, (level_a, x_a, y_a) in enumerate(self.death_positions):
            if i in checked:
                continue
            cluster = [(level_a, x_a, y_a)]
            for j, (level_b, x_b, y_b) in enumerate(self.death_positions):
                if j <= i or j in checked:
                    continue
                if level_a == level_b and abs(x_a - x_b) < radius and abs(y_a - y_b) < radius:
                    cluster.append((level_b, x_b, y_b))
                    checked.add(j)
            if len(cluster) >= min_deaths:
                avg_x = sum(p[1] for p in cluster) / len(cluster)
                avg_y = sum(p[2] for p in cluster) / len(cluster)
                hotspots.append({"level": level_a, "x": round(avg_x), "y": round(avg_y), "deaths": len(cluster)})
        return hotspots

    def summary_report(self):
        report_lines = ["=== PLAYTEST TELEMETRY SUMMARY ==="]
        report_lines.append(f"Total events logged: {len(self.events)}")
        report_lines.append(f"Total deaths: {len(self.death_positions)}")
        for level, times in sorted(self.level_times.items()):
            avg_time = sum(times) / len(times)
            report_lines.append(f"Level {level}: completed {len(times)} time(s), avg {avg_time:.1f}s")
        hotspots = self.find_death_hotspots()
        if hotspots:
            report_lines.append("Death hotspots (likely unfair/unclear hazards):")
            for spot in hotspots:
                report_lines.append(f"  Level {spot['level']} near ({spot['x']}, {spot['y']}): {spot['deaths']} deaths")
        else:
            report_lines.append("No death hotspots detected yet - keep collecting sessions.")
        return "\n".join(report_lines)

    def save_to_file(self, filename="playtest_log.json"):
        with open(filename, "w") as f:
            json.dump(self.events, f, indent=2)


